import { test, expect, type APIRequestContext } from '@playwright/test';

function makeEmail(prefix: string): string {
  const rand = Math.random().toString(36).slice(2, 7);
  return `${prefix}-${Date.now()}-${rand}@example.com`;
}

async function loginUser(
  request: APIRequestContext,
  email: string,
  nickname: string
): Promise<{ id: string; email: string; nickname: string }> {
  const sendRes = await request.post('/api/auth/send-code', { data: { email } });
  expect(sendRes.status(), 'send-code 应返回 200').toBe(200);
  const sendJson = await sendRes.json();
  expect(sendJson.devCode).toMatch(/^\d{6}$/);

  const verifyRes = await request.post('/api/auth/verify-code', {
    data: { email, code: sendJson.devCode, nickname },
  });
  expect(verifyRes.status(), 'verify-code 应返回 200').toBe(200);
  const verifyJson = await verifyRes.json();
  expect(verifyJson.ok).toBe(true);
  return verifyJson.user;
}

test.describe.serial('帖子多途径分享与站内私信分享加固盲测 E2E 套件', () => {
  test('1. API 安全隔离、参数边界、重复接收人去重与并发分享计数一致性', async ({ browser }) => {
    const ctxA = await browser.newContext();
    const ctxB = await browser.newContext();
    const ctxC = await browser.newContext();
    const anonCtx = await browser.newContext();

    try {
      const suffix = Date.now().toString().slice(-4);
      const emailA = makeEmail('share-api-a');
      const emailB = makeEmail('share-api-b');
      const emailC = makeEmail('share-api-c');

      const userA = await loginUser(ctxA.request, emailA, `分享作者${suffix}`);
      const userB = await loginUser(ctxB.request, emailB, `接收好友乙${suffix}`);
      const userC = await loginUser(ctxC.request, emailC, `旁观者丙${suffix}`);

      // 关注关系便于验证候选排序
      expect((await ctxA.request.post(`/api/users/${userB.id}/follow`)).status()).toBe(200);

      const postContent = `接口边界校验动态-${Date.now()} 测试多途径与私信分享`;
      const createRes = await ctxA.request.post('/api/posts', { data: { content: postContent } });
      expect(createRes.status()).toBe(201);
      const postId: string = (await createRes.json()).post.id;

      // 1) 未登录访问候选与私信分享接口必须返回 401
      expect((await anonCtx.request.get('/api/messages/share-recipients')).status()).toBe(401);
      expect(
        (
          await anonCtx.request.post(`/api/posts/${postId}/share-dm`, {
            data: { recipientIds: [userB.id] },
          })
        ).status()
      ).toBe(401);

      // 2) 好友候选接口：非法 limit 返回 400；正常查询不含本人且绝不泄露邮箱
      expect((await ctxA.request.get('/api/messages/share-recipients?limit=0')).status()).toBe(400);
      expect((await ctxA.request.get('/api/messages/share-recipients?limit=99')).status()).toBe(400);

      const recRes = await ctxA.request.get(
        `/api/messages/share-recipients?q=${encodeURIComponent(userB.nickname)}`
      );
      expect(recRes.status()).toBe(200);
      const recText = await recRes.text();
      expect(recText, '好友候选列表严禁泄露任何用户邮箱').not.toContain(emailB);
      expect(recText, '好友候选列表严禁泄露本人邮箱').not.toContain(emailA);
      const recJson = JSON.parse(recText);
      expect(Array.isArray(recJson.recipients)).toBe(true);
      expect(recJson.recipients.some((u: { id: string }) => u.id === userA.id)).toBe(false);
      expect(recJson.recipients.some((u: { id: string }) => u.id === userB.id)).toBe(true);

      // 3) share-dm 非法参数与不存在资源拦截
      expect(
        (await ctxA.request.post(`/api/posts/${postId}/share-dm`, { data: { recipientIds: [] } })).status()
      ).toBe(400);
      expect(
        (
          await ctxA.request.post(`/api/posts/${postId}/share-dm`, {
            data: { recipientIds: [userA.id] },
          })
        ).status()
      ).toBe(400);
      expect(
        (
          await ctxA.request.post(`/api/posts/${postId}/share-dm`, {
            data: { recipientIds: Array.from({ length: 11 }, (_, i) => `fake-user-${i}`) },
          })
        ).status()
      ).toBe(400);
      expect(
        (
          await ctxA.request.post(`/api/posts/${postId}/share-dm`, {
            data: { recipientIds: [userB.id], note: '评'.repeat(1005) },
          })
        ).status()
      ).toBe(400);
      expect(
        (
          await ctxA.request.post('/api/posts/non-existent-post-id/share-dm', {
            data: { recipientIds: [userB.id] },
          })
        ).status()
      ).toBe(404);
      expect(
        (
          await ctxA.request.post(`/api/posts/${postId}/share-dm`, {
            data: { recipientIds: ['non-existent-user-id'] },
          })
        ).status()
      ).toBe(404);

      // 4) 重复 recipientIds 自动去重：仅发 1 条且 sharesCount 仅 +1
      const dedupNote = `去重校验附言-${Date.now()}`;
      const dedupRes = await ctxA.request.post(`/api/posts/${postId}/share-dm`, {
        data: { recipientIds: [userB.id, userB.id], note: dedupNote },
      });
      expect(dedupRes.status()).toBe(201);
      const dedupJson = await dedupRes.json();
      expect(dedupJson.ok).toBe(true);
      expect(dedupJson.sentCount).toBe(1);
      expect(dedupJson.sharesCount).toBe(1);
      expect(dedupJson.messages).toHaveLength(1);
      expect(dedupJson.messages[0].sharedPost?.id).toBe(postId);
      expect(dedupJson.messages[0].sharedPost?.unavailable).toBe(false);

      // 5) 私信权限隔离：用户 C 绝不可看到 A 分享给 B 的私信与附言
      const convCText = await (await ctxC.request.get('/api/messages/conversations')).text();
      expect(convCText).not.toContain(dedupNote);
      expect(convCText).not.toContain(postId);
      const threadCText = await (await ctxC.request.get(`/api/messages/with/${userA.id}`)).text();
      expect(threadCText).not.toContain(dedupNote);
      expect(threadCText).not.toContain(postId);

      // 6) 多渠道 /share 兼容无 body、合法 channel、拒绝非法 channel 及并发累加准确性
      const badChannel = await ctxA.request.post(`/api/posts/${postId}/share`, {
        data: { channel: 'invalid_channel' },
      });
      expect(badChannel.status()).toBe(400);

      const [s1, s2, s3] = await Promise.all([
        ctxA.request.post(`/api/posts/${postId}/share`),
        ctxA.request.post(`/api/posts/${postId}/share`, { data: { channel: 'copy_link' } }),
        ctxA.request.post(`/api/posts/${postId}/share`, { data: { channel: 'copy_text' } }),
      ]);
      expect(s1.status()).toBe(200);
      expect(s2.status()).toBe(200);
      expect(s3.status()).toBe(200);

      // 7) 批量多人无附言分享给 B 和 C（+2），总分享数应为 1 + 3 + 2 = 6
      const batchRes = await ctxA.request.post(`/api/posts/${postId}/share-dm`, {
        data: { recipientIds: [userB.id, userC.id], note: '' },
      });
      expect(batchRes.status()).toBe(201);
      const batchJson = await batchRes.json();
      expect(batchJson.sentCount).toBe(2);
      expect(batchJson.sharesCount).toBe(6);

      const postDetailRes = await ctxA.request.get(`/api/posts/${postId}`);
      expect(postDetailRes.status()).toBe(200);
      expect((await postDetailRes.json()).post.sharesCount).toBe(6);

      // 校验 C 的会话列表存在分享动态标识及未读
      const convCJson = await (await ctxC.request.get('/api/messages/conversations')).json();
      expect(convCJson.totalUnread).toBeGreaterThanOrEqual(1);
      const convWithA = convCJson.conversations.find(
        (c: { peer: { id: string } }) => c.peer.id === userA.id
      );
      expect(convWithA).toBeTruthy();
      expect(convWithA.lastMessage.sharedPostId).toBe(postId);

      // 回归校验：普通文本私信空内容仍返回 400
      expect(
        (await ctxA.request.post(`/api/messages/with/${userB.id}`, { data: { content: '   ' } })).status()
      ).toBe(400);
    } finally {
      await ctxA.close();
      await ctxB.close();
      await ctxC.close();
      await anonCtx.close();
    }
  });

  test('2. 信息流与详情页多途径分享菜单、匿名访客私信分享登录引导、深色模式与移动端防溢出', async ({
    page,
    browser,
  }) => {
    const pageErrors: string[] = [];
    page.on('pageerror', (err) => pageErrors.push(err.message));
    await page.setViewportSize({ width: 1440, height: 900 });

    const authorCtx = await browser.newContext();
    let postId = '';
    const postText = `类X多途径分享展示帖-${Date.now()}`;
    try {
      await loginUser(authorCtx.request, makeEmail('ui-share-author'), '分享展示作者');
      const createRes = await authorCtx.request.post('/api/posts', { data: { content: postText } });
      expect(createRes.status()).toBe(201);
      postId = (await createRes.json()).post.id;
    } finally {
      await authorCtx.close();
    }

    // 1) 未登录访客直达 /posts/:id 点击分享菜单 -> 通过私信发送，应弹出登录弹窗而非报错
    await page.goto(`/posts/${postId}`);
    const detailDialog = page.getByRole('dialog').first();
    await expect(detailDialog).toBeVisible({ timeout: 10000 });
    await expect(detailDialog).toContainText(postText);

    await detailDialog.getByRole('button', { name: /分享/i }).first().click();
    const detailMenu = page.getByRole('menu').first();
    await expect(detailMenu).toBeVisible({ timeout: 8000 });
    await expect(detailMenu.getByRole('menuitem', { name: /复制链接/i }).first()).toBeVisible();
    await expect(detailMenu.getByRole('menuitem', { name: /私信/i }).first()).toBeVisible();
    await expect(
      detailMenu.getByRole('menuitem', { name: /复制分享文案|复制文案/i }).first()
    ).toBeVisible();

    await detailMenu.getByRole('menuitem', { name: /私信/i }).first().click();
    const authEmailInput = page
      .getByPlaceholder(/邮箱|email/i)
      .or(page.locator('input[type="email"]'))
      .first();
    await expect(authEmailInput).toBeVisible({ timeout: 8000 });

    // 2) 登录后回到首页信息流测试复制链接与复制分享文案多途径操作
    await loginUser(page.request, makeEmail('ui-share-viewer'), '多途径访客');
    await page.goto('/');
    const card = page.locator('article').filter({ hasText: postText }).first();
    await expect(card).toBeVisible({ timeout: 10000 });

    // 仅打开菜单并按 Escape 关闭，不应提前累加分享数
    await card.getByRole('button', { name: /分享/i }).first().click();
    await expect(page.getByRole('menu').first()).toBeVisible();
    await page.keyboard.press('Escape');
    await expect(page.getByRole('menu')).toHaveCount(0);

    // 选择“复制链接”
    await card.getByRole('button', { name: /分享/i }).first().click();
    const copyLinkPromise = page.waitForResponse(
      (res) => res.url().includes(`/api/posts/${postId}/share`) && res.request().method() === 'POST'
    );
    await page.getByRole('menu').first().getByRole('menuitem', { name: /复制链接/i }).first().click();
    expect((await copyLinkPromise).status()).toBe(200);

    // 选择“复制分享文案”
    await card.getByRole('button', { name: /分享/i }).first().click();
    const copyTextPromise = page.waitForResponse(
      (res) => res.url().includes(`/api/posts/${postId}/share`) && res.request().method() === 'POST'
    );
    await page
      .getByRole('menu')
      .first()
      .getByRole('menuitem', { name: /复制分享文案|复制文案/i })
      .first()
      .click();
    const copyTextRes = await copyTextPromise;
    expect(copyTextRes.status()).toBe(200);
    expect((await copyTextRes.json()).sharesCount).toBe(2);

    // 3) 移动端 375px 展开分享菜单不引发横向溢出
    await page.setViewportSize({ width: 375, height: 812 });
    await card.getByRole('button', { name: /分享/i }).first().click();
    await expect(page.getByRole('menu').first()).toBeVisible();
    const overflow = await page.evaluate(
      () => document.documentElement.scrollWidth - window.innerWidth
    );
    expect(overflow).toBeLessThanOrEqual(2);

    expect(pageErrors, '多途径分享菜单交互不应产生前端异常').toEqual([]);
  });

  test('3. 帖子详情页通过私信分享给好友 -> 接收方私信卡片展示与直达 -> 原帖删除后优雅降级', async ({
    page,
    browser,
  }) => {
    const pageErrorsA: string[] = [];
    const pageErrorsB: string[] = [];
    page.on('pageerror', (err) => pageErrorsA.push(err.message));
    await page.setViewportSize({ width: 1440, height: 900 });

    const ctxB = await browser.newContext();
    const pageB = await ctxB.newPage();
    pageB.on('pageerror', (err) => pageErrorsB.push(err.message));
    await pageB.setViewportSize({ width: 1440, height: 900 });

    try {
      const suffix = Date.now().toString().slice(-4);
      const userA = await loginUser(page.request, makeEmail('e2e-flow-a'), `主讲人甲${suffix}`);
      const userB = await loginUser(ctxB.request, makeEmail('e2e-flow-b'), `听众好友乙${suffix}`);

      await page.request.post(`/api/users/${userB.id}/follow`);

      const postText = `端到端私信卡片分享全文-${Date.now()} 欢迎点击查看细节`;
      const createRes = await page.request.post('/api/posts', { data: { content: postText } });
      expect(createRes.status()).toBe(201);
      const postId: string = (await createRes.json()).post.id;

      // 用户 A 在 /posts/:id 详情页通过私信分享给用户 B
      await page.goto(`/posts/${postId}`);
      const detailDialog = page.getByRole('dialog').first();
      await expect(detailDialog).toBeVisible({ timeout: 10000 });

      await detailDialog.getByRole('button', { name: /分享/i }).first().click();
      const menu = page.getByRole('menu').first();
      await expect(menu).toBeVisible({ timeout: 8000 });
      await menu.getByRole('menuitem', { name: /私信/i }).first().click();

      const dmDialog = page.getByRole('dialog').last();
      await expect(dmDialog).toBeVisible({ timeout: 10000 });
      await expect(dmDialog).toContainText(postText);

      // 搜索并选择好友 B，填写附言并发送
      const searchBox = dmDialog.getByPlaceholder(/搜索/i).first();
      await expect(searchBox).toBeVisible();
      await searchBox.fill(userB.nickname);

      const peerOption = dmDialog.getByText(userB.nickname).first();
      await expect(peerOption).toBeVisible({ timeout: 8000 });
      await peerOption.click();

      const customNote = `强推这篇干货-${suffix}`;
      const noteBox = dmDialog.getByPlaceholder(/附言|留言|说点什么/i).first();
      await expect(noteBox).toBeVisible();
      await noteBox.fill(customNote);

      const shareDmPromise = page.waitForResponse(
        (res) => res.url().includes(`/api/posts/${postId}/share-dm`) && res.request().method() === 'POST'
      );
      await dmDialog.getByRole('button', { name: /发送/i }).last().click();
      const shareDmRes = await shareDmPromise;
      expect(shareDmRes.status()).toBe(201);
      expect((await shareDmRes.json()).sharesCount).toBe(1);

      // 用户 B 进入私信页查看会话列表与分享动态卡片
      await pageB.goto('/messages');
      const peerConvBtn = pageB.getByText(userA.nickname).first();
      await expect(peerConvBtn).toBeVisible({ timeout: 10000 });
      await peerConvBtn.click();

      await expect(pageB.getByText(customNote).first()).toBeVisible({ timeout: 10000 });
      const sharedPostCard = pageB.getByText(postText).first();
      await expect(sharedPostCard).toBeVisible({ timeout: 10000 });

      // 点击私信中的动态卡片，直达打开原帖详情弹窗
      await sharedPostCard.click();
      const openedDetail = pageB.getByRole('dialog').first();
      await expect(openedDetail).toBeVisible({ timeout: 10000 });
      await expect(openedDetail).toContainText(postText);
      await openedDetail.getByRole('button', { name: /关闭弹窗/i }).first().click();
      await expect(pageB.getByRole('dialog')).toHaveCount(0);

      // 用户 A 删除原帖后，用户 B 重新加载私信会话仍正常渲染删除占位提示且无异常
      const delRes = await page.request.delete(`/api/posts/${postId}`);
      expect(delRes.status()).toBe(200);

      const threadAfterDelRes = await ctxB.request.get(`/api/messages/with/${userA.id}`);
      expect(threadAfterDelRes.status()).toBe(200);
      const threadAfterDelJson = await threadAfterDelRes.json();
      const sharedMsg = threadAfterDelJson.messages.find(
        (m: { sharedPost?: { id?: string } | null }) => m.sharedPost?.id === postId
      );
      expect(sharedMsg).toBeTruthy();
      expect(sharedMsg.sharedPost.unavailable).toBe(true);

      await pageB.reload();
      await pageB.getByText(userA.nickname).first().click();
      await expect(pageB.getByText(customNote).first()).toBeVisible({ timeout: 10000 });
      await expect(
        pageB.getByText(/已删除|已被删除|不可查看|失效/i).first()
      ).toBeVisible({ timeout: 10000 });

      expect(pageErrorsA, '分享方页面不应产生前端异常').toEqual([]);
      expect(pageErrorsB, '接收方页面不应产生前端异常').toEqual([]);
    } finally {
      await pageB.close();
      await ctxB.close();
    }
  });
});

