-- Incremental idempotent schema for social profile, follows, comment replies, and direct messages

CREATE TABLE IF NOT EXISTS user_profiles (
  user_id TEXT PRIMARY KEY,
  avatar_url TEXT NOT NULL DEFAULT '',
  bio TEXT NOT NULL DEFAULT '',
  updated_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS user_follows (
  follower_id TEXT NOT NULL,
  following_id TEXT NOT NULL,
  created_at TEXT NOT NULL,
  PRIMARY KEY (follower_id, following_id)
);

CREATE INDEX IF NOT EXISTS idx_user_follows_follower
  ON user_follows (follower_id, created_at DESC);

CREATE INDEX IF NOT EXISTS idx_user_follows_following
  ON user_follows (following_id, created_at DESC);

CREATE TABLE IF NOT EXISTS comment_replies (
  id TEXT PRIMARY KEY,
  comment_id TEXT NOT NULL,
  post_id TEXT NOT NULL,
  author_id TEXT NOT NULL,
  reply_to_user_id TEXT,
  content TEXT NOT NULL,
  created_at TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_comment_replies_comment
  ON comment_replies (comment_id, created_at ASC);

CREATE INDEX IF NOT EXISTS idx_comment_replies_post
  ON comment_replies (post_id, created_at ASC);

CREATE INDEX IF NOT EXISTS idx_comment_replies_author
  ON comment_replies (author_id, created_at DESC);

CREATE TABLE IF NOT EXISTS direct_messages (
  id TEXT PRIMARY KEY,
  conversation_key TEXT NOT NULL,
  sender_id TEXT NOT NULL,
  receiver_id TEXT NOT NULL,
  content TEXT NOT NULL,
  is_read INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_dm_conv_created
  ON direct_messages (conversation_key, created_at ASC);

CREATE INDEX IF NOT EXISTS idx_dm_receiver_read
  ON direct_messages (receiver_id, is_read, sender_id, created_at DESC);

CREATE INDEX IF NOT EXISTS idx_dm_sender_created
  ON direct_messages (sender_id, created_at DESC);

-- Incremental idempotent schema for notifications

CREATE TABLE IF NOT EXISTS notifications (
  id TEXT PRIMARY KEY,
  recipient_id TEXT NOT NULL,
  actor_id TEXT NOT NULL,
  type TEXT NOT NULL CHECK (type IN ('comment', 'like', 'follow')),
  post_id TEXT,
  comment_id TEXT,
  content_preview TEXT NOT NULL DEFAULT '',
  is_read INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_notifications_recipient_created
  ON notifications (recipient_id, created_at DESC);

CREATE INDEX IF NOT EXISTS idx_notifications_recipient_type_created
  ON notifications (recipient_id, type, created_at DESC);

CREATE INDEX IF NOT EXISTS idx_notifications_recipient_unread
  ON notifications (recipient_id, is_read);

CREATE INDEX IF NOT EXISTS idx_notifications_post_id
  ON notifications (post_id);

CREATE INDEX IF NOT EXISTS idx_notifications_dedup
  ON notifications (recipient_id, actor_id, type, post_id, is_read);

-- Incremental idempotent schema for post metrics (views, bookmarks, shares) and user bookmarks

CREATE TABLE IF NOT EXISTS post_metrics (
  post_id TEXT PRIMARY KEY,
  views_count INTEGER NOT NULL DEFAULT 0,
  bookmarks_count INTEGER NOT NULL DEFAULT 0,
  shares_count INTEGER NOT NULL DEFAULT 0,
  updated_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS post_bookmarks (
  post_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  created_at TEXT NOT NULL,
  PRIMARY KEY (post_id, user_id)
);

CREATE INDEX IF NOT EXISTS idx_post_bookmarks_user_created
  ON post_bookmarks (user_id, created_at DESC);

CREATE INDEX IF NOT EXISTS idx_post_bookmarks_post
  ON post_bookmarks (post_id);

