test.describe.serial('发布功能优化、三栏独立滚动、收藏直达与通知分类已读加固盲测套件', () => {
  test('1. 品牌改名dev社区、三栏独立滚动、吸顶Tab同宽对齐、右侧搜索、紧凑卡片与配色/隐形滚动条审计', async ({ page, browser }) => {
    const pageErrors: string[] = [];
    page.on('pageerror', (err) => pageErrors.push(err.message));
    await page.setViewportSize({ width: 1440, height: 900 });

    const ctxFollowed = await browser.newContext();
    const ctxStranger = await browser.newContext();
    const anonCtx = await browser.newContext();
    try {
      // 健康检查与隐藏管理入口守卫
      const healthRes = await page.request.get('/api/health');
      expect(healthRes.status()).toBe(200);
      expect((await healthRes.json()).ok).toBe(true);

      // 未登录查询关注流与非法排序参数校验
      expect((await anonCtx.request.get('/api/posts?sort=following')).status()).toBe(401);
      expect((await anonCtx.request.get('/api/posts?sort=invalid_sort')).status()).toBe(400);

      const viewer = await loginUser(page.request, makeEmail('layout-viewer'), '前端探索者');
      const followedAuthor = await loginUser(ctxFollowed.request, makeEmail('layout-followed'), '已关注大佬');
      await loginUser(ctxStranger.request, makeEmail('layout-stranger'), '未关注路人');

      // 关注目标作者
      expect((await page.request.post(`/api/users/${followedAuthor.id}/follow`)).status()).toBe(200);

      const uniqueSearchKey = `SearchKey${Date.now().toString().slice(-5)}`;
      const followedPostText = `已关注作者的干货分享 ${uniqueSearchKey} #TypeScript`;
      const strangerPostText = `未关注路人的动态-${Date.now()} #随笔`;

      // 发布多条动态确保中心动态流可滚动
      expect(
        (await ctxFollowed.request.post('/api/posts', { data: { content: followedPostText } })).status()
      ).toBe(201);
      expect(
        (await ctxStranger.request.post('/api/posts', { data: { content: strangerPostText } })).status()
      ).toBe(201);
      for (let i = 0; i < 7; i += 1) {
        const res = await ctxStranger.request.post('/api/posts', {
          data: {
            content: `滚动填充动态 #${i + 1} - ${Date.now()}\n用于验证三栏独立滚动、吸顶Tab与动态卡片紧凑间隔。`,
          },
        });
        expect(res.status()).toBe(201);
      }

      // 验证 API 返回默认站点名及关注流严格过滤
      const followingApiRes = await page.request.get('/api/posts?sort=following');
      expect(followingApiRes.status()).toBe(200);
      const followingApiJson = await followingApiRes.json();
      expect(followingApiJson.siteName).toContain('dev社区');
      expect(
        followingApiJson.posts.some((p: { content: string }) => p.content.includes(followedPostText)),
        '关注流应包含已关注作者动态'
      ).toBe(true);
      expect(
        followingApiJson.posts.some((p: { content: string }) => p.content.includes(strangerPostText)),
        '关注流不得混入未关注作者动态'
      ).toBe(false);

      await page.goto('/');
      await expect(page.locator('a[href="/admin"]')).toHaveCount(0);
      await expect(page.locator('a[href="/admin/"]')).toHaveCount(0);

      // 1) 品牌名改为 dev社区，且旧 Hero 标语彻底移除
      await expect(page.getByText(/dev社区/i).first()).toBeVisible({ timeout: 10000 });
      await expect(page.getByText('轻图文 · 慢生活灵感角落')).toHaveCount(0);
      await expect(page.getByText('把日常瞬间写成光')).toHaveCount(0);

      // 2) 全局隐形滚动条与去红紫渐变配色审计
      const styleAudit = await page.evaluate(() => {
        const docStyle = getComputedStyle(document.documentElement);
        const bodyStyle = getComputedStyle(document.body);
        let hasWebkitScrollbarHide = false;
        for (const sheet of Array.from(document.styleSheets)) {
          try {
            for (const rule of Array.from(sheet.cssRules || [])) {
              if (rule.cssText && rule.cssText.includes('::-webkit-scrollbar') && rule.cssText.includes('none')) {
                hasWebkitScrollbarHide = true;
              }
            }
          } catch {
            // ignore cross-origin stylesheet
          }
        }
        const buttons = Array.from(document.querySelectorAll('button'));
        const hasOldPinkPurpleGradient = buttons.some((btn) => {
          const bg = getComputedStyle(btn).backgroundImage || '';
          return bg.includes('244, 63, 94') && (bg.includes('217, 70, 239') || bg.includes('99, 102, 241'));
        });
        return {
          scrollbarNone: docStyle.scrollbarWidth === 'none' || bodyStyle.scrollbarWidth === 'none',
          hasWebkitScrollbarHide,
          hasOldPinkPurpleGradient,
        };
      });
      expect(
        styleAudit.scrollbarNone || styleAudit.hasWebkitScrollbarHide,
        '应启用全局隐藏滚动条样式'
      ).toBe(true);
      expect(styleAudit.hasOldPinkPurpleGradient, '主按钮不应再使用旧版红紫 AI 渐变').toBe(false);

      // 3) 吸顶 Tab（最新 / 最热 / 我的关注）可见且与动态卡片同宽
      const latestTab = page
        .getByRole('tab', { name: /最新/ })
        .or(page.getByRole('button', { name: /^最新$/ }))
        .first();
      const hotTab = page
        .getByRole('tab', { name: /最热/ })
        .or(page.getByRole('button', { name: /^最热$/ }))
        .first();
      const followTab = page
        .getByRole('tab', { name: /我的关注/ })
        .or(page.getByRole('button', { name: /我的关注/ }))
        .first();
      await expect(latestTab).toBeVisible({ timeout: 10000 });
      await expect(hotTab).toBeVisible();
      await expect(followTab).toBeVisible();

      const articles = page.locator('article');
      await expect(articles.nth(1)).toBeVisible({ timeout: 10000 });
      const cardBox0 = await articles.nth(0).boundingBox();
      const cardBox1 = await articles.nth(1).boundingBox();
      expect(cardBox0 && cardBox1).toBeTruthy();
      if (cardBox0 && cardBox1) {
        const verticalGap = cardBox1.y - (cardBox0.y + cardBox0.height);
        expect(verticalGap, '动态卡片上下间距应紧凑（<= 14px）').toBeLessThanOrEqual(14);
        expect(verticalGap, '动态卡片不应重叠').toBeGreaterThanOrEqual(2);
      }

      const tabBarWidth = await page.evaluate(() => {
        const tabEl = document.querySelector('[role="tablist"]');
        if (tabEl) return tabEl.getBoundingClientRect().width;
        const btns = Array.from(document.querySelectorAll('button'));
        const latest = btns.find((b) => b.textContent?.trim() === '最新');
        return latest?.parentElement?.getBoundingClientRect().width || 0;
      });
      if (cardBox0 && tabBarWidth > 0) {
        expect(
          Math.abs(tabBarWidth - cardBox0.width),
          '最新/最热/我的关注 Tab 栏宽度应与动态卡片栏保持一致'
        ).toBeLessThanOrEqual(36);
      }

      // 4) 三栏各自独立滚动验证：滚动中间动态流容器时，左右两侧导航栏 Y 坐标保持不动，且吸顶 Tab 固定在顶部
      const leftAside = page.locator('aside').first();
      const rightAside = page.locator('aside').nth(1);
      await expect(leftAside).toBeVisible();
      await expect(rightAside).toBeVisible();
      const leftBefore = await leftAside.boundingBox();
      const rightBefore = await rightAside.boundingBox();

      const scrollResult = await page.evaluate(() => {
        let el: HTMLElement | null = document.querySelector('article');
        while (el && el !== document.body && el !== document.documentElement) {
          const style = getComputedStyle(el);
          if (
            (style.overflowY === 'auto' || style.overflowY === 'scroll') &&
            el.scrollHeight > el.clientHeight + 20
          ) {
            el.scrollTop = 360;
            return { scrolledIndependent: true, scrollTop: el.scrollTop };
          }
          el = el.parentElement;
        }
        window.scrollTo(0, 360);
        return { scrolledIndependent: false, scrollTop: window.scrollY };
      });
      expect(scrollResult.scrolledIndependent, '中间动态流应作为独立滚动容器而非整页联动滚动').toBe(true);
      expect(scrollResult.scrollTop).toBeGreaterThan(100);

      const leftAfter = await leftAside.boundingBox();
      const rightAfter = await rightAside.boundingBox();
      const latestTabAfterScroll = await latestTab.boundingBox();
      if (leftBefore && leftAfter && rightBefore && rightAfter) {
        expect(Math.abs(leftAfter.y - leftBefore.y), '滚动动态流时左侧导航栏不应跟着偏移').toBeLessThanOrEqual(2);
        expect(Math.abs(rightAfter.y - rightBefore.y), '滚动动态流时右侧发现栏不应跟着偏移').toBeLessThanOrEqual(2);
      }
      expect(latestTabAfterScroll, '滚动后吸顶 Tab 栏应仍可见').not.toBeNull();
      if (latestTabAfterScroll) {
        expect(latestTabAfterScroll.y, 'Tab 栏滚动后应吸附在视口顶部').toBeLessThanOrEqual(80);
      }

      // 5) 切换「我的关注」Tab 验证前端仅展示关注作者动态
      await followTab.click();
      await expect(page.locator('article').filter({ hasText: followedPostText }).first()).toBeVisible({ timeout: 10000 });
      await expect(page.locator('article').filter({ hasText: strangerPostText })).toHaveCount(0);
      await latestTab.click();

      // 6) 搜索框位于右侧导航栏顶部（热门话题上方）且能实际筛选动态
      const rightSearchInput = rightAside
        .getByPlaceholder(/搜索/)
        .or(rightAside.locator('input[type="search"], input[type="text"], input:not([type])'))
        .first();
      const trendingHeading = rightAside.getByRole('heading', { name: /热门话题/ }).first();
      await expect(rightSearchInput).toBeVisible({ timeout: 10000 });
      await expect(trendingHeading).toBeVisible();

      const searchBox = await rightSearchInput.boundingBox();
      const trendingBox = await trendingHeading.boundingBox();
      if (searchBox && trendingBox && cardBox0) {
        expect(searchBox.x, '搜索框应位于动态流右侧导航栏内').toBeGreaterThanOrEqual(cardBox0.x + cardBox0.width - 20);
        expect(searchBox.y, '搜索框应位于右侧导航栏顶部（热门话题上方）').toBeLessThan(trendingBox.y);
      }

      await rightSearchInput.fill(uniqueSearchKey);
      await rightSearchInput.press('Enter');
      await expect(page.locator('article').filter({ hasText: followedPostText }).first()).toBeVisible({ timeout: 10000 });
      await expect(page.locator('article').filter({ hasText: strangerPostText })).toHaveCount(0);

      expect(viewer.id).toBeTruthy();
      expect(pageErrors, '布局、滚动与筛选过程不应出现未捕获前端异常').toEqual([]);
    } finally {
      await ctxFollowed.close();
      await ctxStranger.close();
      await anonCtx.close();
    }
  });

  test('2. X.com 风格无标题发布、拖拽/粘贴图片、正文 #话题 解析边界与左侧独立收藏页闭环', async ({ page, browser }) => {
    const pageErrors: string[] = [];
    page.on('pageerror', (err) => pageErrors.push(err.message));
    await page.setViewportSize({ width: 1440, height: 900 });

    const ctxOther = await browser.newContext();
    const anonCtx = await browser.newContext();
    try {
      const author = await loginUser(page.request, makeEmail('x-compose-a'), '极客作者');
      await loginUser(ctxOther.request, makeEmail('x-compose-b'), '其他用户');

      // API 输入校验边界：空正文、超长正文、恶意 imageUrl、未登录均需拦截
      expect((await anonCtx.request.post('/api/posts', { data: { content: '未登录尝试' } })).status()).toBe(401);
      expect((await page.request.post('/api/posts', { data: { content: '   ' } })).status()).toBe(400);
      expect((await page.request.post('/api/posts', { data: { content: 'a'.repeat(5001) } })).status()).toBe(400);
      expect(
        (
          await page.request.post('/api/posts', {
            data: { content: '恶意链接拦截测试', imageUrl: 'javascript:alert(1)' },
          })
        ).status()
      ).toBe(400);

      // 正文 #话题 提取与去重/上限校验
      const tagA = `Rust${Date.now().toString().slice(-4)}`;
      const tagB = `Workers${Date.now().toString().slice(-4)}`;
      const apiHashtagRes = await page.request.post('/api/posts', {
        data: {
          content: `测试自动提取 #${tagA}，重复 #${tagA} 以及 #${tagB}! 纯井号 # 不应入库`,
        },
      });
      expect(apiHashtagRes.status()).toBe(201);
      const apiHashtagPost = (await apiHashtagRes.json()).post;
      expect(apiHashtagPost.tags).toEqual(expect.arrayContaining([tagA, tagB]));
      expect(apiHashtagPost.tags.filter((t: string) => t === tagA).length).toBe(1);

