      await composerTextarea.evaluate((el, base64Png) => {
        const bin = atob(base64Png);
        const bytes = new Uint8Array(bin.length);
        for (let i = 0; i < bin.length; i += 1) bytes[i] = bin.charCodeAt(i);
        const file = new File([bytes], 'dragged-shot.png', { type: 'image/png' });
        const dt = new DataTransfer();
        dt.items.add(file);
        el.dispatchEvent(new DragEvent('dragover', { dataTransfer: dt, bubbles: true, cancelable: true }));
        el.dispatchEvent(new DragEvent('drop', { dataTransfer: dt, bubbles: true, cancelable: true }));
      }, TINY_PNG.toString('base64'));

      await expect(composerForm.locator('img').first()).toBeVisible({ timeout: 8000 });

      // 输入纯正文 + #话题 并提交发布
      const uiTag = `DragPaste${Date.now().toString().slice(-4)}`;
