      );
      await publishedCard.getByRole('button', { name: /收藏/i }).first().click();
      expect((await bookmarkResp).status()).toBe(200);

      // 安全隐私校验：其他用户严禁查看本人收藏，未登录返回 401
      expect((await anonCtx.request.get('/api/users/me/activity?tab=bookmarks')).status()).toBe(401);
      expect((await ctxOther.request.get(`/api/users/${author.id}/activity?tab=bookmarks`)).status()).toBe(403);

      const bookmarksNav = leftAside
        .getByRole('button', { name: /收藏/ })
        .or(leftAside.getByRole('link', { name: /收藏/ }))
        .first();
      await expect(bookmarksNav).toBeVisible({ timeout: 10000 });
      await bookmarksNav.click();
      await expect(page).toHaveURL(/\/bookmarks/);

      const bookmarkedCard = page.locator('article').filter({ hasText: uiBody }).first();
      await expect(bookmarkedCard).toBeVisible({ timeout: 10000 });

      // 在收藏页直接取消收藏，卡片应立即移出列表
