      expect((await unbookmarkResp).status()).toBe(200);
      await expect(page.locator('article').filter({ hasText: uiBody })).toHaveCount(0, { timeout: 10000 });

      expect(pageErrors, '无标题发布、图片拖拽粘贴与收藏页交互不应存在前端异常').toEqual([]);
    } finally {
      await ctxOther.close();
      await anonCtx.close();
    }
  });

  test('3. 通知红点按分类点击即已读、分项独立扣减、安全隔离与并发幂等校验', async ({ page, browser }) => {
    const pageErrors: string[] = [];
    page.on('pageerror', (err) => pageErrors.push(err.message));
    await page.setViewportSize({ width: 1440, height: 900 });

    const ctxB = await browser.newContext();
    const ctxC = await browser.newContext();
    const anonCtx = await browser.newContext();
    try {
      const userA = await loginUser(page.request, makeEmail('notif-v2-a'), '收件开发者A');
      await loginUser(ctxB.request, makeEmail('notif-v2-b'), '互动开发者B');
      await loginUser(ctxC.request, makeEmail('notif-v2-c'), '无关旁观者C');

      // 权限与非法参数边界
      expect((await anonCtx.request.post('/api/notifications/read', { data: { type: 'comment' } })).status()).toBe(401);
      expect((await page.request.post('/api/notifications/read', { data: { type: 'invalid_cat' } })).status()).toBe(400);

      // 用户 A 发帖，用户 B 依次触发 关注 + 点赞 + 评论 三类通知
      const postRes = await page.request.post('/api/posts', {
        data: { content: `分分类红点测试动态-${Date.now()} #Notify` },
      });
      expect(postRes.status()).toBe(201);
      const postId = (await postRes.json()).post.id as string;

      expect((await ctxB.request.post(`/api/users/${userA.id}/follow`)).status()).toBe(200);
      expect((await ctxB.request.post(`/api/posts/${postId}/like`)).status()).toBe(200);
      expect(
        (await ctxB.request.post(`/api/posts/${postId}/comments`, { data: { content: '精准分类测试评论' } })).status()
      ).toBe(201);

      // 校验分类型未读数初始化均 >= 1
      const initialSummary = await (await page.request.get('/api/notifications/unread-count')).json();
      expect(initialSummary.unreadByType.comment).toBeGreaterThanOrEqual(1);
      expect(initialSummary.unreadByType.like).toBeGreaterThanOrEqual(1);
      expect(initialSummary.unreadByType.follow).toBeGreaterThanOrEqual(1);
      expect(initialSummary.notificationsUnread).toBe(
        initialSummary.unreadByType.comment +
          initialSummary.unreadByType.like +
          initialSummary.unreadByType.follow
      );

      // IDOR 防护：无关用户 C 按分类标为已读严禁影响用户 A
      expect((await ctxC.request.post('/api/notifications/read', { data: { type: 'comment' } })).status()).toBe(200);
      const afterIdor = await (await page.request.get('/api/notifications/unread-count')).json();
      expect(afterIdor.unreadByType.comment).toBe(initialSummary.unreadByType.comment);

      // 进入通知中心 UI，验证进入时不自动清零全部红点，点击各分类 Tab 才对应清空该分类未读
      await page.goto('/');
      const leftAside = page.locator('aside').first();
      const notifNav = leftAside
        .getByRole('button', { name: /通知/ })
        .or(leftAside.getByRole('link', { name: /通知/ }))
        .first();
      await notifNav.click();
      await expect(page).toHaveURL(/\/notifications/);

      const commentTab = page
        .getByRole('tab', { name: /评论/ })
        .or(page.getByRole('button', { name: /评论/ }))
        .first();
      const likeTab = page
        .getByRole('tab', { name: /点赞/ })
        .or(page.getByRole('button', { name: /点赞/ }))
        .first();
      const followTab = page
        .getByRole('tab', { name: /关注/ })
        .or(page.getByRole('button', { name: /关注/ }))
        .first();
      await expect(commentTab).toBeVisible({ timeout: 10000 });
      await expect(likeTab).toBeVisible();
      await expect(followTab).toBeVisible();

      // 1) 点击「评论」分类 -> 仅评论未读归零，点赞与关注保持未读
      const readCommentPromise = page.waitForResponse(
        (r) => r.url().includes('/api/notifications/read') && r.request().method() === 'POST'
      );
      await commentTab.click();
      expect((await readCommentPromise).status()).toBe(200);
      await expect
        .poll(async () => (await (await page.request.get('/api/notifications/unread-count')).json()).unreadByType)
        .toMatchObject({ comment: 0 });
      const afterComment = await (await page.request.get('/api/notifications/unread-count')).json();
      expect(afterComment.unreadByType.like).toBeGreaterThanOrEqual(1);
      expect(afterComment.unreadByType.follow).toBeGreaterThanOrEqual(1);

      // 2) 点击「点赞」分类 -> 点赞未读归零，关注仍保持未读
      const readLikePromise = page.waitForResponse(
        (r) => r.url().includes('/api/notifications/read') && r.request().method() === 'POST'
      );
      await likeTab.click();
      expect((await readLikePromise).status()).toBe(200);
      await expect
        .poll(async () => (await (await page.request.get('/api/notifications/unread-count')).json()).unreadByType)
        .toMatchObject({ comment: 0, like: 0 });
      const afterLike = await (await page.request.get('/api/notifications/unread-count')).json();
      expect(afterLike.unreadByType.follow).toBeGreaterThanOrEqual(1);

      // 3) 点击「关注」分类 -> 所有未读清零
      const readFollowPromise = page.waitForResponse(
        (r) => r.url().includes('/api/notifications/read') && r.request().method() === 'POST'
      );
      await followTab.click();
      expect((await readFollowPromise).status()).toBe(200);
      await expect
        .poll(async () => (await (await page.request.get('/api/notifications/unread-count')).json()).notificationsUnread)
        .toBe(0);

      // 4) 并发重复标记同一分类已读具备幂等性且计数非负
      const concurrentReads = await Promise.all([
        page.request.post('/api/notifications/read', { data: { type: 'follow' } }),
        page.request.post('/api/notifications/read', { data: { type: 'follow' } }),
        page.request.post('/api/notifications/read', { data: { type: 'all' } }),
      ]);
      for (const r of concurrentReads) {
        expect(r.status()).toBe(200);
        const j = await r.json();
        expect(j.unreadCount).toBe(0);
      }

      expect(pageErrors, '通知分类批量已读流程不应存在未捕获前端异常').toEqual([]);
    } finally {
      await ctxB.close();
      await ctxC.close();
      await anonCtx.close();
    }
  });
});

