      await anonPage.goto(`/posts/${postId}`);
      await expect(anonPage.getByText(title1).first()).toBeVisible({ timeout: 10000 });
      await expect(anonPage.getByText(content1).first()).toBeVisible({ timeout: 10000 });
      await expect
        .poll(async () => (await (await page.request.get(`/api/posts/${postId}`)).json()).post.viewsCount)
        .toBeGreaterThan(viewsBeforeShareJump);

      // 访问不存在的分享 URL 应优雅展示错误提示且无 JS 崩溃
      await anonPage.goto('/posts/non-existent-share-id');
      await expect(anonPage.getByText(/不存在|无法加载|未找到|已删除/i).first()).toBeVisible({ timeout: 10000 });
      expect(anonErrors, '直达有效及无效分享链接均不应触发前端异常').toEqual([]);
      await anonPage.close();

      // 进入个人主页 UI 核对「收藏」标签页展示
      const sidebar = page.locator('aside').first();
      await sidebar
        .getByRole('button', { name: /主页/ })
        .or(sidebar.getByRole('link', { name: /主页/ }))
        .first()
        .click();
      const bookmarksTab = page
        .getByRole('tab', { name: /收藏/ })
        .or(page.getByRole('button', { name: /收藏/ }))
        .first();
      await expect(bookmarksTab).toBeVisible({ timeout: 10000 });
      await bookmarksTab.click();
      await expect(page.getByText(title1).first()).toBeVisible({ timeout: 10000 });

      // 删帖级联清理：删除后收藏列表不再残留且详情返回 404
      expect((await page.request.delete(`/api/posts/${postId}`)).status()).toBe(200);
      expect((await page.request.get(`/api/posts/${postId}`)).status()).toBe(404);
      const bookmarksAfterDel = await (await page.request.get(`/api/users/${userA.id}/activity?tab=bookmarks`)).json();
      expect(bookmarksAfterDel.items.some((p: { id: string }) => p.id === postId)).toBe(false);
      expect(pageErrors).toEqual([]);
    } finally {
      await ctxB.close();
      await anonCtx.close();
    }
  });

  test('2. 右侧导航（热门话题、推荐关注）接口契约、隐私脱敏、三栏几何布局与交互闭环', async ({ page, browser }) => {
