      const hotTag = `趋势热词${Date.now().toString().slice(-4)}`;
      const otherTag = `普通标签${Date.now().toString().slice(-4)}`;
      const hotPostTitle = `热词精选帖子-${Date.now()}`;
      const otherPostTitle = `其他分类帖子-${Date.now()}`;

      // 发布多篇带热词标签的动态提升其热度排名
      for (let i = 0; i < 3; i += 1) {
        const res = await ctxCreator.request.post('/api/posts', {
          data: {
            title: i === 0 ? hotPostTitle : `${hotPostTitle}-${i}`,
            content: '测试热门话题实时聚合排序', 
            tags: [hotTag],
          },
        });
