      const recJson = JSON.parse(recRawText);
      expect(recJson.users.some((u: { id: string }) => u.id === viewer.id), '推荐关注不应包含当前登录用户本人').toBe(false);
      expect(recJson.users.some((u: { id: string }) => u.id === creator.id)).toBe(true);

      // 浏览器 1440px 宽屏验证三栏几何布局：左导航 < 居中列表 < 右侧发现栏
