      const liveDm = `WebSocket秒达私信-${Date.now()}`;
      expect(
        (await ctxB.request.post(`/api/messages/with/${userA.id}`, { data: { content: liveDm } })).status()
      ).toBe(201);
      await expect(page.getByText(liveDm).first()).toBeVisible({ timeout: 10000 });
