    await expect(dialog.getByText(postContent).first()).toBeVisible();

    // 几何验证：桌面端详情弹窗为宽幅左右双栏结构（图片在左，评论输入互动区在右）
    const dialogImg = dialog
      .locator(`img[src="${imageUrl}"]`)
      .or(dialog.getByRole('img', { name: postTitle }))
      .first();
