    await page
      .getByPlaceholder(/正文|分享|想法/i)
      .or(page.locator('textarea'))
      .first()
      .fill('体验新版图片裁剪与旋转编辑后发布的第一篇图文');

    const uploadPromise = page.waitForResponse(
